/**
 * Builds src/demo/spixi.iife.js from component ESM sources so demos load real
 * component code as a classic script (file:// blocks module imports).
 * Supersedes hand-inlined copies (DECISIONS.md #35). Run after any component
 * change: node scripts/build-demo-bundle.mjs
 * Icons ship separately in icons.iife.js (generated by generate-icons.mjs).
 *
 * Exposed names are derived from `export function/const` declarations in each
 * source (no manual list to drift). The build FAILS on: residual import/export
 * lines the stripper can't handle, cross-file top-level symbol collisions,
 * imports from icons.js other than `icon`/`ICONS` (only those are aliased in
 * the wrapper — anything else would be undefined at runtime), and a corrupt
 * emitted artifact (NUL byte / lone surrogate / truncated write — #175).
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const FILES = [
  'src/components/strings-runtime.js', // Phase 3 #3: getStrings/setStrings — window.SL default source, before every consumer
  'src/components/money.js',        // #143: shared money helpers — before every consumer
  'src/components/disc.js',         // #170: per-glyph disc gradient index (pure fn)
  'src/components/timestamp.js',
  'src/components/avatar.js',
  'src/components/chatlist-item.js',
  'src/components/button.js',
  'src/components/topbar.js',
  'src/components/bottomnav.js',
  'src/components/chip.js',
  'src/components/search-field.js',
  'src/components/highlight.js',
  'src/components/badge.js',
  'src/components/txlist-item.js',
  'src/components/overlay.js',
  'src/components/sheet.js',
  'src/components/modal.js',
  'src/components/banner.js',
  'src/components/toast.js',
  'src/components/callbar.js',
  'src/components/message-bubble.js',
  'src/components/composer.js',
  'src/components/typed-bubbles.js',
  'src/components/reactions.js',
  'src/components/typing-indicator.js',
  'src/components/scroll-latest.js',
  'src/components/message-menu.js',
  'src/components/media-bubble.js',
  'src/components/system-notice.js',
  'src/components/lazy-history.js',
  'src/components/attach-sheet.js',
  'src/components/channel-sheet.js',
  'src/components/member-sheet.js',
  'src/components/media-viewer.js',
  'src/components/call-overlay.js',
  'src/components/contact-request.js',
  'src/components/chats-row-menu.js',
  'src/components/chats-swipe.js',
  'src/components/chats-shell.js',
  'src/components/chats-header.js',
  'src/components/apps-icon.js',
  'src/components/apps-item.js',
  'src/components/apps-menu.js',
  'src/components/apps-shell.js',
  'src/components/apps-recents.js',
  'src/components/apps-header.js',
  'src/components/apps-add.js',
  'src/components/apps-details.js',
  'src/components/apps-discover.js',
  'src/components/apps-feed.js',
  'src/components/wallet-hero.js',
  'src/components/wallet-shell.js',
  'src/components/wallet-send.js',
  'src/components/qr.js',
  'src/components/wallet-receive.js',
  'src/components/tip-sheet.js',
  'src/components/chat-select.js',
  'src/components/chat-info.js',
  'src/components/contacts-shell.js',   // Phase 1 #2: FAB picker · add-contact · group setup
  'src/bridge/contacts-page.js',        // Track D: contacts takeover boundary (mountContacts) — after contacts-shell
  'src/components/scan-shell.js',       // Phase 1 #3: scan takeover (mock camera in the demo)
  'src/components/lock-shell.js',       // Phase 1 #4: unlock/confirm + change-encryption-password
  'src/components/settings-shell.js',   // #146: exports backupStatusParts — must precede settings-backup
  'src/components/settings-backup.js',
  'src/components/settings-screens.js', // #147: chat appearance · privacy · notifications · security tiers
  'src/components/settings-app.js',     // §9b: downloads · dev log · contributors (imports settingsConfirm from settings-shell)
  'src/components/launch-shell.js',     // Phase 1 #5: welcome/create/restore/retry/tail (imports passwordField + ENC_MIN from lock-shell — must follow it)
  'src/components/backup-nudge.js',     // periodic backup prompt (legacy #backup-prompt parity, Damir 2026-07-06)
  'src/components/rating-nudge.js',     // rate-app prompt (legacy #ratingModal replacement — showRatingPrompt mirror)
  'src/bridge/native.js',               // Phase 3 #173: real-bridge transport core (in the bundle so smoke can drive it; demos stay mock-wired)
  'src/bridge/scan-page.js',            // Phase 3 #173: scan real-bridge adapter (first repoint target) — after scan-shell + native
  'src/bridge/lock-page.js',            // Phase 3 #173: lock/encpass real-bridge adapters — after lock-shell + native
];
// Only these icons.js names are aliased in the wrapper below.
const ICON_ALIASES = ['icon', 'ICONS'];

const expose = [];             // export order across FILES
const declaredIn = new Map();  // top-level symbol -> file (collision detection)
let body = '';

for (const f of FILES) {
  const raw = readFileSync(join(root, f), 'utf8');

  // Guard: imports from icons.js may only use the aliased names.
  for (const m of raw.matchAll(/^\s*import\s+([^;]+?)\s+from\s+['"][^'"]*\bicons\.js['"]/gm)) {
    const names = m[1].replace(/[{}]/g, '').split(',')
      .map((s) => s.trim().split(/\s+as\s+/)[0]).filter(Boolean);
    const bad = names.filter((n) => !ICON_ALIASES.includes(n));
    if (bad.length) {
      throw new Error(`${f}: imports { ${bad.join(', ')} } from icons.js — bundle wrapper only aliases ${ICON_ALIASES.join('/')}; these would be undefined at runtime`);
    }
  }

  // Derive the expose list + collect top-level declarations for collision checks.
  const exported = [...raw.matchAll(/^export\s+(?:function|const)\s+([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]);
  expose.push(...exported);
  // let/var included (audit r3): top-level `let` dups bypassed the named check
  const declared = [...raw.matchAll(/^(?:export\s+)?(?:function|const|let|var)\s+([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]);
  for (const name of declared) {
    if (declaredIn.has(name)) {
      throw new Error(`symbol collision: "${name}" declared at top level in both ${declaredIn.get(name)} and ${f} — last one would silently win in the shared bundle scope`);
    }
    declaredIn.set(name, f);
  }

  const src = raw
    .replace(/^import .*$/gm, '')          // deps resolved in shared scope
    .replace(/^export function /gm, 'function ')
    .replace(/^export const /gm, 'const ');

  // Fail loudly on any import/export form the stripping regexes above missed
  // (indented, multi-line, `export default`, `export {}` …) — they would
  // syntax-error or silently break the classic-script bundle.
  for (const line of src.split('\n')) {
    if (/^\s*(import|export)\b/.test(line)) {
      throw new Error(`${f}: unhandled import/export survived stripping — fix the source or the stripper:\n  ${line.trim()}`);
    }
  }

  body += `\n/* ---- ${f} ---- */\n` + src;
}

const out = `/* GENERATED by scripts/build-demo-bundle.mjs — DO NOT EDIT.
 * Real component sources bundled for file:// demos. Requires icons.iife.js first.
 */
(function () {
  var icon = window.SpixiIcons.icon;
  var ICONS = window.SpixiIcons.ICONS;
${body}
  window.Spixi = { ${expose.map((n) => n + ': ' + n).join(', ')} };
})();
`;
// Syntax smoke test before writing — catches multi-line-import orphans and any
// other stripping artifact that would only explode at load time in a browser.
try {
  new Function(out);
} catch (e) {
  throw new Error('bundle failed syntax check (stripping artifact?): ' + e.message);
}

/* Integrity (#175): NO binary garbage may reach the artifact. A single NUL byte
 * makes git treat spixi.iife.js — and EVERY built shell that inlines it — as
 * BINARY (undiffable, unreviewable), and a NUL landing in code rather than in a
 * comment kills the bundle at load. A lone surrogate is the same class of IO
 * damage (a UTF-16 pair split by a truncated read/write). No component source
 * contains either, so a hit here means the READ path corrupted the input — fail
 * loudly ("generators fail loudly", DECISIONS #46) instead of shipping it.
 * NB: the NUL needle is BUILT with fromCharCode — this generator must never carry
 * a literal control character itself. */
const NUL = String.fromCharCode(0);
/** Offset of the first lone (unpaired) UTF-16 surrogate, or -1. */
function firstLoneSurrogate(text) {
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c >= 0xD800 && c <= 0xDBFF) {                  // high half — must be followed by a low half
      const n = text.charCodeAt(i + 1);
      if (!(n >= 0xDC00 && n <= 0xDFFF)) return i;
      i++;                                             // valid pair — skip its low half
    } else if (c >= 0xDC00 && c <= 0xDFFF) return i;   // low half with no high half
  }
  return -1;
}
const CORRUPT_HINT = ' — IO/mount corruption (#175), NOT a source defect (no component source contains it).'
  + ' Re-run `node scripts/build-demo-bundle.mjs` from a LOCAL terminal on the real files (never a sandboxed mount);'
  + ' if it reproduces, the source READ is corrupt — reset/re-clone the working tree before rebuilding.';

let hit = out.indexOf(NUL);
if (hit !== -1) throw new Error('bundle contains a NUL byte at offset ' + hit + CORRUPT_HINT);
hit = firstLoneSurrogate(out);
if (hit !== -1) throw new Error('bundle contains a lone surrogate at offset ' + hit + CORRUPT_HINT);

const outPath = join(root, 'src/demo/spixi.iife.js');
writeFileSync(outPath, out);

// Post-write read-back: the in-memory string was verified clean, so anything wrong
// on disk came from the WRITE path — the same class that truncates files on the
// corrupted mount. Catches both a NUL byte and a short/truncated write.
const written = readFileSync(outPath);
const expectedBytes = Buffer.byteLength(out, 'utf8');
if (written.includes(0)) {
  throw new Error('bundle WRITE corrupted: NUL byte at offset ' + written.indexOf(0)
    + ' on disk (the generated string was clean)' + CORRUPT_HINT);
}
if (written.length !== expectedBytes) {
  throw new Error('bundle WRITE truncated: ' + written.length + ' bytes on disk, expected ' + expectedBytes + CORRUPT_HINT);
}

console.log('bundle written:', out.length, 'bytes,', expose.length, 'exports:', expose.join(', '));
